requete:
SELECT ?mal ?tv ?movie ?season WHERE {
  ?item wdt:P4086 ?mal .
  OPTIONAL { ?item wdt:P4983 ?tv }
  OPTIONAL { ?item wdt:P4947 ?movie }
  FILTER(BOUND(?tv) || BOUND(?movie))
  FILTER NOT EXISTS { ?item wdt:P31 ?bad . VALUES ?bad { wd:Q14946528 wd:Q91615393 } }
  BIND(EXISTS { ?item wdt:P31 ?c . VALUES ?c { wd:Q100269041 wd:Q3464665 } } AS ?season)
}
